 "content": "from collections import deque


def transform(grid):
    """Paint the 3x3-interior cells of nonzero regions from their color seeds."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]

    # Each nonzero component is a shape. Within it, the seed color propagates
    # through the shape; when there are several seeds, use shortest path distance.
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] == 0 or seen[sr][sc]:
                continue
            comp = []
            q = deque([(sr, sc)])
            seen[sr][sc] = True
            while q:
                r, c = q.popleft()
                comp.append((r, c))
                for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0 and not seen[nr][nc]:
                        seen[nr][nc] = True
                        q.append((nr, nc))
            seeds = [(r, c, grid[r][c]) for r, c in comp if grid[r][c] not in (0, 1)]
            if not seeds:
                continue
            # BFS distances from each seed, restricted to this component.
            dists = []
            for ar, ac, color in seeds:
                dist = {(ar, ac): 0}
                q = deque([(ar, ac)])
                while q:
                    r, c = q.popleft()
                    for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0 and (nr, nc) not in dist:
                            dist[(nr, nc)] = dist[(r, c)] + 1
                            q.append((nr, nc))
                dists.append((dist, color, ar, ac))
            for r, c in comp:
                if grid[r][c] not in (1,) and grid[r][c] not in (0,):
                    continue
                if grid[r][c] != 1 or r == 0 or c == 0 or r == h-1 or c == w-1:
                    continue
                if not all(grid[rr][cc] != 0 for rr in (r-1, r, r+1) for cc in (c-1, c, c+1)):
                    continue
                _, color, _, _ = min(dists, key=lambda item: (item[0].get((r,c), 10**9), item[2], item[3]))
                out[r][c] = color
    return out


